//! Physical custody for the selected original local Legacy MCP client.
//! This joins its real service driver and stdio owners. It does not claim
//! to join SDK protocol/logging callbacks which hold no Agentd owners.

use std::collections::HashMap;
use std::ffi::OsString;
use std::path::PathBuf;
use std::sync::Arc;
use std::sync::Mutex as StdMutex;
use std::sync::Weak;
use std::sync::atomic::AtomicBool;
use std::sync::atomic::Ordering;
use std::time::Duration;

use anyhow::Result;
use anyhow::anyhow;
use anyhow::ensure;
use codex_config::types::McpServerEnvVar;
use rmcp::service::QuitReason;
use rmcp::service::RoleClient;
use rmcp::service::RunningService;
use tokio::sync::Mutex;
use tokio::task::JoinHandle;

use super::ClientState;
use super::PendingTransport;
use super::RmcpClient;
use crate::McpProtocolMode;
use crate::elicitation_client_service::ElicitationClientService;
use crate::stdio_server_launcher::LocalStdioServerLauncher;
use crate::stdio_server_launcher::OriginalStdioShutdownCustody;
use crate::stdio_server_launcher::OriginalStdioShutdownObservation;
use crate::stdio_server_launcher::StdioServerLauncher;

type OriginalService = RunningService<RoleClient, ElicitationClientService>;

/// Empty custody creates neither an MCP peer nor operation permission.
/// Only the concrete local Legacy constructor below installs a client.
pub struct OriginalMcpClientShutdown {
    fallback_cwd: PathBuf,
    stdio: Arc<OriginalStdioShutdownCustody>,
    stopped: AtomicBool,
    state: StdMutex<OriginalClientState>,
}

struct OriginalClientState {
    constructor_used: bool,
    client: Option<Weak<RmcpClient>>,
    service: Option<Arc<OriginalService>>,
    extra_services: Vec<Arc<OriginalService>>,
    driver: Option<Arc<OriginalDriverJob>>,
}

struct OriginalDriverJob {
    state: Mutex<OriginalDriverState>,
}

struct OriginalDriverState {
    handle: Option<JoinHandle<Result<OriginalDriverJoined, String>>>,
    result: Option<Result<OriginalDriverJoined, String>>,
}

#[derive(Clone, Debug)]
enum OriginalDriverJoined {
    Cancelled,
    Closed,
}

/// A cleanup observation, never a business or authority capability.
/// Callers cannot fill these fields or deserialize them from a peer.
pub struct OriginalMcpClientShutdownObservation {
    driver: Option<OriginalDriverJoined>,
    stdio: OriginalStdioShutdownObservation,
}

impl OriginalMcpClientShutdownObservation {
    pub fn require_original_ready_client_joined(&self) -> Result<()> {
        ensure!(
            self.driver.is_some(),
            "original MCP service never became an owned driver"
        );
        self.stdio
            .require_original_child_exited()
            .map_err(|error| anyhow!("original MCP child was not joined: {error}"))
    }
}

impl OriginalMcpClientShutdown {
    pub fn new(fallback_cwd: PathBuf) -> Arc<Self> {
        Arc::new(Self {
            fallback_cwd,
            stdio: OriginalStdioShutdownCustody::new(),
            stopped: AtomicBool::new(false),
            state: StdMutex::new(OriginalClientState {
                constructor_used: false,
                client: None,
                service: None,
                extra_services: Vec::new(),
                driver: None,
            }),
        })
    }

    pub fn request_stop(&self) {
        self.stopped.store(true, Ordering::Release);
        // Poison grants cleanup access only, never another start.
        let state = self
            .state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        if let Some(service) = &state.service {
            service.cancellation_token().cancel();
        }
        for service in &state.extra_services {
            service.cancellation_token().cancel();
        }
        drop(state);
        self.stdio.request_stop();
    }

    fn reserve_original_constructor(&self) -> Result<()> {
        let mut state = self
            .state
            .lock()
            .map_err(|_| anyhow!("original MCP client custody is poisoned"))?;
        ensure!(
            !self.stopped.load(Ordering::Acquire) && !state.constructor_used,
            "original MCP client custody cannot be restarted"
        );
        state.constructor_used = true;
        Ok(())
    }

    fn retain_original_client(&self, client: &Arc<RmcpClient>) -> Result<()> {
        let mut state = self
            .state
            .lock()
            .map_err(|_| anyhow!("original MCP client custody is poisoned"))?;
        ensure!(
            state.constructor_used && state.client.is_none(),
            "original MCP client cannot be replaced"
        );
        state.client = Some(Arc::downgrade(client));
        Ok(())
    }

    pub(super) fn retain_original_service(&self, service: &Arc<OriginalService>) -> Result<()> {
        let poisoned = self.state.is_poisoned();
        let mut state = self
            .state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        // The original handshake already created this driver. Even poison
        // must retain it for cleanup before returning the refusal.
        let duplicate = state.service.is_some() || state.driver.is_some();
        if duplicate {
            state.extra_services.push(Arc::clone(service));
        } else {
            state.service = Some(Arc::clone(service));
        }
        if poisoned || !state.constructor_used || duplicate || self.stopped.load(Ordering::Acquire)
        {
            service.cancellation_token().cancel();
            return Err(anyhow!("original MCP service publication was refused"));
        }
        Ok(())
    }

    fn start_original_driver_join(&self) -> Option<Arc<OriginalDriverJob>> {
        let mut state = self
            .state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        if let Some(job) = &state.driver {
            return Some(Arc::clone(job));
        }
        let service = state.service.take()?;
        let extra_services = std::mem::take(&mut state.extra_services);
        // The outer registry has already joined the actual startup work.
        // This real service and the resulting handle move into one registered
        // cleanup task without an await gap. Waiter cancellation cannot
        // detach the task or take away the SDK service handle.
        let handle = tokio::spawn(async move {
            let duplicate = !extra_services.is_empty();
            let mut actual = Vec::with_capacity(1 + extra_services.len());
            actual.push(service);
            actual.extend(extra_services);
            let mut primary = None;
            let mut first_error = duplicate
                .then(|| "original MCP startup produced more than one service".to_string());
            for service in actual {
                match join_actual_original_service(service).await {
                    Ok(joined) => {
                        if primary.is_none() {
                            primary = Some(joined);
                        }
                    }
                    Err(error) => {
                        if first_error.is_none() {
                            first_error = Some(error);
                        } else {
                            tracing::error!(error = %error, "additional original service join failure");
                        }
                    }
                }
            }
            if let Some(error) = first_error {
                return Err(error);
            }
            primary.ok_or_else(|| "original service join result missing".into())
        });
        let job = Arc::new(OriginalDriverJob {
            state: Mutex::new(OriginalDriverState {
                handle: Some(handle),
                result: None,
            }),
        });
        state.driver = Some(Arc::clone(&job));
        Some(job)
    }

    /// The configured startup registry must first join its real startup jobs.
    /// It then retains the actual cleanup task which drives this method.
    pub async fn join_original_client(&self) -> Result<OriginalMcpClientShutdownObservation> {
        self.request_stop();
        let mut first_error = self
            .state
            .is_poisoned()
            .then(|| anyhow!("original MCP client custody was poisoned"));
        let client = self
            .state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .client
            .as_ref()
            .and_then(Weak::upgrade);
        if let Some(client) = client {
            // Only the client retained synchronously by our constructor is
            // reachable; no caller-supplied replacement is accepted.
            let previous = {
                let mut state = client.state.lock().await;
                std::mem::replace(&mut *state, ClientState::Closed)
            };
            match previous {
                ClientState::Connecting {
                    transport: Some(PendingTransport::Stdio { mut transport }),
                } => {
                    use rmcp::transport::Transport;
                    if let Err(error) = transport.close().await
                        && first_error.is_none()
                    {
                        first_error =
                            Some(anyhow!("original pending MCP transport close: {error}"));
                    }
                }
                // Ready's Arc was retained before the first subsequent await.
                // Dropping this state cancels the original retained-call lifetime.
                other => drop(other),
            }
        }
        let driver = match self.start_original_driver_join() {
            Some(job) => match job.join_original().await {
                Ok(joined) => Some(joined),
                Err(error) => {
                    if first_error.is_none() {
                        first_error = Some(anyhow!(error));
                    }
                    None
                }
            },
            None => None,
        };
        let stdio = self
            .stdio
            .join_original_stdio()
            .await
            .map_err(|error| anyhow!("original MCP stdio owners did not join: {error}"));
        match (first_error, stdio) {
            (Some(error), Err(cleanup)) => {
                tracing::error!(error = %cleanup, "additional original MCP stdio cleanup failure");
                Err(error)
            }
            (Some(error), Ok(_)) => Err(error),
            (None, Err(error)) => Err(error),
            (None, Ok(stdio)) => Ok(OriginalMcpClientShutdownObservation { driver, stdio }),
        }
    }
}

async fn join_actual_original_service(
    service: Arc<OriginalService>,
) -> Result<OriginalDriverJoined, String> {
    let mut retained = service;
    loop {
        retained.cancellation_token().cancel();
        match Arc::try_unwrap(retained) {
            Ok(service) => {
                return match service.cancel().await {
                    Ok(QuitReason::Cancelled) => Ok(OriginalDriverJoined::Cancelled),
                    Ok(QuitReason::Closed) => Ok(OriginalDriverJoined::Closed),
                    Ok(QuitReason::JoinError(error)) => {
                        Err(format!("original MCP service subtask failed: {error}"))
                    }
                    Ok(_) => Err("original MCP service returned an unknown quit reason".into()),
                    Err(error) => Err(format!(
                        "actual original MCP service driver failed to join: {error}"
                    )),
                };
            }
            Err(service) => retained = service,
        }
        // Actual retained users must release their service references.
        // This is no request retry or join proof: the only success above
        // awaits the original SDK JoinHandle without a timeout.
        tokio::time::sleep(Duration::from_millis(1)).await;
    }
}

impl OriginalDriverJob {
    async fn join_original(&self) -> Result<OriginalDriverJoined, String> {
        let mut state = self.state.lock().await;
        if let Some(result) = &state.result {
            return result.clone();
        }
        let result = match state.handle.as_mut() {
            Some(handle) => match handle.await {
                Ok(result) => result,
                Err(error) => Err(format!("original MCP driver cleanup task failed: {error}")),
            },
            None => Err("original MCP driver join custody is unavailable".into()),
        };
        state.handle.take();
        state.result = Some(result.clone());
        result
    }
}

impl Drop for OriginalMcpClientShutdown {
    fn drop(&mut self) {
        self.request_stop();
    }
}

impl RmcpClient {
    /// The original configured local Legacy constructor, with real custody.
    pub async fn new_stdio_client_with_owned_shutdown(
        program: OsString,
        args: Vec<OsString>,
        env: Option<HashMap<OsString, OsString>>,
        env_vars: &[McpServerEnvVar],
        cwd: Option<String>,
        owner: Arc<OriginalMcpClientShutdown>,
    ) -> std::io::Result<Arc<Self>> {
        if !cfg!(target_os = "linux") {
            return Err(std::io::Error::new(
                std::io::ErrorKind::Unsupported,
                "owned MCP shutdown requires the Linux local Legacy profile",
            ));
        }
        owner
            .reserve_original_constructor()
            .map_err(std::io::Error::other)?;
        let launcher: Arc<dyn StdioServerLauncher> =
            Arc::new(LocalStdioServerLauncher::new_with_owned_shutdown(
                owner.fallback_cwd.clone(),
                Arc::clone(&owner.stdio),
            ));
        let mut client = Self::new_stdio_client_with_protocol_mode(
            program,
            args,
            env,
            env_vars,
            cwd,
            launcher,
            McpProtocolMode::Legacy,
        )
        .await?;
        client.original_owned_shutdown = Some(Arc::clone(&owner));
        let client = Arc::new(client);
        owner
            .retain_original_client(&client)
            .map_err(std::io::Error::other)?;
        Ok(client)
    }
}

//! Custody for one actual configured local Legacy MCP startup.
//! Admission is closed before cleanup. Actual startup and driver handles
//! remain owned through waiter cancellation; no count substitutes for join.

use std::sync::Arc;
use std::sync::Mutex as StdMutex;
use std::sync::atomic::AtomicBool;
use std::sync::atomic::Ordering;

use anyhow::Result;
use anyhow::anyhow;
use anyhow::ensure;
use codex_config::McpServerTransportConfig;
use codex_rmcp_client::OriginalMcpClientShutdown;
use codex_rmcp_client::OriginalMcpClientShutdownObservation;
use tokio::sync::Mutex;
use tokio::sync::Notify;
use tokio::task::JoinHandle;
use tokio::task::JoinSet;
use tokio_util::sync::CancellationToken;

use crate::McpProtocolMode;
use crate::McpRuntimeInput;
use crate::McpStartupPolicy;
use crate::mcp::CODEX_APPS_MCP_SERVER_NAME;
use crate::rmcp_client::ManagedClient;
use crate::rmcp_client::StartupOutcomeError;

type StartupOutput = (String, Result<ManagedClient, StartupOutcomeError>);

/// Externally retained before the actual configured initializer is polled.
/// This empty object cannot choose a server, command, credential or policy.
pub struct OriginalMcpRuntimeShutdown {
    stopped: AtomicBool,
    state: StdMutex<OriginalRuntimeState>,
    changed: Notify,
    cleanup: StdMutex<Option<Arc<OriginalCleanupJob>>>,
}

struct OriginalRuntimeState {
    constructor_used: bool,
    constructing: bool,
    startup: Option<CancellationToken>,
    client: Option<Arc<OriginalMcpClientShutdown>>,
    startup_jobs: Vec<Arc<OriginalStartupJob>>,
    custody_failure: Option<String>,
}

pub(crate) struct OriginalMcpConstructionGuard {
    owner: Arc<OriginalMcpRuntimeShutdown>,
}

struct OriginalStartupJob {
    state: Mutex<OriginalStartupJobState>,
}

struct OriginalStartupJobState {
    handle: Option<JoinHandle<OriginalStartupJoined>>,
    joined: Option<OriginalStartupJoined>,
}

#[derive(Clone)]
struct OriginalStartupJoined {
    ready: usize,
    errors: Vec<String>,
}

struct OriginalCleanupJob {
    state: Mutex<OriginalCleanupJobState>,
}

struct OriginalCleanupJobState {
    handle: Option<JoinHandle<Result<Arc<OriginalMcpRuntimeShutdownObservation>, String>>>,
    result: Option<Result<Arc<OriginalMcpRuntimeShutdownObservation>, String>>,
}

/// Actual cleanup facts, not business completion or authority permission.
pub struct OriginalMcpRuntimeShutdownObservation {
    startups: Vec<OriginalStartupJoined>,
    client: Option<OriginalMcpClientShutdownObservation>,
}

impl OriginalMcpRuntimeShutdownObservation {
    pub fn require_original_ready_runtime_joined(&self) -> Result<()> {
        ensure!(
            self.startups.len() == 1,
            "original MCP startup custody is incomplete"
        );
        let startup = &self.startups[0];
        ensure!(
            startup.ready == 1 && startup.errors.is_empty(),
            "original MCP startup did not join with one successful configured client"
        );
        OriginalMcpClientShutdownObservation::require_original_ready_client_joined(
            self.client
                .as_ref()
                .ok_or_else(|| anyhow!("original MCP client was never constructed"))?,
        )
    }
}

impl OriginalMcpRuntimeShutdown {
    pub fn new() -> Arc<Self> {
        Arc::new(Self {
            stopped: AtomicBool::new(false),
            state: StdMutex::new(OriginalRuntimeState {
                constructor_used: false,
                constructing: false,
                startup: None,
                client: None,
                startup_jobs: Vec::new(),
                custody_failure: None,
            }),
            changed: Notify::new(),
            cleanup: StdMutex::new(None),
        })
    }

    pub(crate) fn reserve_original_input(
        self: &Arc<Self>,
        input: &McpRuntimeInput,
    ) -> Result<OriginalMcpConstructionGuard> {
        ensure!(
            cfg!(target_os = "linux"),
            "owned MCP cleanup requires Linux"
        );
        ensure!(
            input.startup_policy == McpStartupPolicy::Eager,
            "owned MCP startup cannot be deferred"
        );
        ensure!(
            input.config.protocol_mode == McpProtocolMode::Legacy,
            "owned MCP startup requires the actual retained Legacy profile"
        );
        ensure!(
            input.tx_event.is_none()
                && input.elicitation_reviewer.is_none()
                && input.elicitation_lifecycle.is_none(),
            "owned MCP profile requires its original threadless handler policy"
        );
        ensure!(
            input.mcp_servers.len() == 1,
            "owned MCP startup requires one explicitly configured server"
        );
        let (name, server) = input
            .mcp_servers
            .iter()
            .next()
            .ok_or_else(|| anyhow!("original MCP server is absent"))?;
        ensure!(
            name != CODEX_APPS_MCP_SERVER_NAME && server.enabled(),
            "owned MCP startup cannot reconnect hosted Apps or a disabled server"
        );
        ensure!(
            server.config().is_local_environment()
                && matches!(
                    &server.config().transport,
                    McpServerTransportConfig::Stdio { .. }
                ),
            "owned MCP shutdown supports the configured local stdio transport only"
        );
        let mut state = self
            .state
            .lock()
            .map_err(|_| anyhow!("original MCP startup custody is poisoned"))?;
        ensure!(
            !self.stopped.load(Ordering::Acquire) && !state.constructor_used,
            "original MCP startup cannot be reopened"
        );
        state.constructor_used = true;
        state.constructing = true;
        state.startup = Some(input.startup_cancellation_token.clone());
        state.client = Some(OriginalMcpClientShutdown::new(
            input.runtime_context.local_process_cwd(),
        ));
        Ok(OriginalMcpConstructionGuard {
            owner: Arc::clone(self),
        })
    }

    pub(crate) fn original_client_custody(&self) -> Result<Arc<OriginalMcpClientShutdown>> {
        let state = self
            .state
            .lock()
            .map_err(|_| anyhow!("original MCP startup custody is poisoned"))?;
        ensure!(
            !self.stopped.load(Ordering::Acquire)
                && state.constructor_used
                && state.custody_failure.is_none(),
            "original MCP construction is no longer admitted"
        );
        state
            .client
            .as_ref()
            .map(Arc::clone)
            .ok_or_else(|| anyhow!("actual MCP construction custody is absent"))
    }

    pub(crate) fn require_original_construction(&self) -> Result<()> {
        let state = self
            .state
            .lock()
            .map_err(|_| anyhow!("original MCP startup custody is poisoned"))?;
        ensure!(
            !self.stopped.load(Ordering::Acquire)
                && state.constructing
                && state.custody_failure.is_none(),
            "actual original MCP construction was cancelled or refused"
        );
        Ok(())
    }

    pub(crate) fn retain_original_startup(&self, mut actual: JoinSet<StartupOutput>) {
        let poisoned = self.state.is_poisoned();
        let mut state = self
            .state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        if poisoned || !state.constructing || !state.startup_jobs.is_empty() {
            state.custody_failure = Some("original startup handle registration was refused".into());
        }
        // No await separates creation of this actual task from registration
        // of its handle. Unlike JoinSet::join_all, one failed child does not
        // discard the remaining original child handles.
        let handle = tokio::spawn(async move {
            let mut joined = OriginalStartupJoined {
                ready: 0,
                errors: Vec::new(),
            };
            while let Some(result) = actual.join_next().await {
                match result {
                    Ok((_name, Ok(client))) => {
                        joined.ready += 1;
                        drop(client);
                    }
                    Ok((name, Err(error))) => joined.errors.push(format!("{name}: {error}")),
                    Err(error) => joined
                        .errors
                        .push(format!("actual MCP startup task: {error}")),
                }
            }
            joined
        });
        state.startup_jobs.push(Arc::new(OriginalStartupJob {
            state: Mutex::new(OriginalStartupJobState {
                handle: Some(handle),
                joined: None,
            }),
        }));
    }

    pub fn request_stop(&self) {
        self.stopped.store(true, Ordering::Release);
        let state = self
            .state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        if let Some(startup) = &state.startup {
            startup.cancel();
        }
        if let Some(client) = &state.client {
            OriginalMcpClientShutdown::request_stop(client);
        }
        drop(state);
        self.changed.notify_waiters();
    }

    /// Starts and retains the real cleanup task before returning its waiter.
    /// Dropping the waiter cannot take the handle or the original result.
    pub fn stop_and_join_original_runtime(
        self: &Arc<Self>,
    ) -> impl std::future::Future<Output = Result<Arc<OriginalMcpRuntimeShutdownObservation>>>
    + Send
    + 'static {
        self.request_stop();
        let job = {
            let mut slot = self
                .cleanup
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            if let Some(job) = slot.as_ref() {
                Arc::clone(job)
            } else {
                let owner = Arc::clone(self);
                let handle = tokio::spawn(async move { owner.join_original_resources().await });
                let job = Arc::new(OriginalCleanupJob {
                    state: Mutex::new(OriginalCleanupJobState {
                        handle: Some(handle),
                        result: None,
                    }),
                });
                *slot = Some(Arc::clone(&job));
                job
            }
        };
        async move {
            job.receive_original_cleanup()
                .await
                .map_err(|error| anyhow!(error))
        }
    }

    async fn join_original_resources(
        self: Arc<Self>,
    ) -> Result<Arc<OriginalMcpRuntimeShutdownObservation>, String> {
        // A cancelled constructor drops its guard before cleanup can snapshot
        // the registered real handles. A stop before reservation rejects start.
        loop {
            let changed = self.changed.notified();
            tokio::pin!(changed);
            changed.as_mut().enable();
            let constructing = self
                .state
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .constructing;
            if !constructing {
                break;
            }
            changed.await;
        }
        let (jobs, client, mut first_error) = {
            let state = self
                .state
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            let failure = if self.state.is_poisoned() || self.cleanup.is_poisoned() {
                Some("original MCP cleanup custody is poisoned".to_string())
            } else {
                state.custody_failure.clone()
            };
            (state.startup_jobs.clone(), state.client.clone(), failure)
        };
        let mut startups = Vec::new();
        for job in jobs {
            let joined = job.join_original_startup().await;
            if first_error.is_none() && !joined.errors.is_empty() {
                first_error = Some(joined.errors.join("; "));
            }
            startups.push(joined);
        }
        // The real startup jobs have ended; no client/service can appear after
        // this cut. Always drive driver/Child cleanup even after startup errors.
        let client = if let Some(client) = client {
            match OriginalMcpClientShutdown::join_original_client(&client).await {
                Ok(observed) => Some(observed),
                Err(error) => {
                    if first_error.is_none() {
                        first_error = Some(error.to_string());
                    } else {
                        tracing::error!(error = %error, "additional original MCP cleanup failure");
                    }
                    None
                }
            }
        } else {
            None
        };
        if let Some(error) = first_error {
            return Err(error);
        }
        Ok(Arc::new(OriginalMcpRuntimeShutdownObservation {
            startups,
            client,
        }))
    }
}

impl Drop for OriginalMcpConstructionGuard {
    fn drop(&mut self) {
        let mut state = self
            .owner
            .state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        state.constructing = false;
        drop(state);
        self.owner.changed.notify_waiters();
    }
}

impl OriginalStartupJob {
    async fn join_original_startup(&self) -> OriginalStartupJoined {
        let mut state = self.state.lock().await;
        if let Some(joined) = &state.joined {
            return joined.clone();
        }
        let joined = match state.handle.as_mut() {
            Some(handle) => match handle.await {
                Ok(joined) => joined,
                Err(error) => OriginalStartupJoined {
                    ready: 0,
                    errors: vec![format!("actual MCP startup join owner: {error}")],
                },
            },
            None => OriginalStartupJoined {
                ready: 0,
                errors: vec!["actual MCP startup handle is missing".into()],
            },
        };
        state.handle.take();
        state.joined = Some(joined.clone());
        joined
    }
}

impl OriginalCleanupJob {
    async fn receive_original_cleanup(
        &self,
    ) -> Result<Arc<OriginalMcpRuntimeShutdownObservation>, String> {
        let mut state = self.state.lock().await;
        if let Some(result) = &state.result {
            return result.clone();
        }
        let result = match state.handle.as_mut() {
            Some(handle) => match handle.await {
                Ok(result) => result,
                Err(error) => Err(format!("actual MCP cleanup owner failed: {error}")),
            },
            None => Err("actual MCP cleanup handle is missing".into()),
        };
        state.handle.take();
        state.result = Some(result.clone());
        result
    }
}

impl Drop for OriginalMcpRuntimeShutdown {
    fn drop(&mut self) {
        self.request_stop();
    }
}

