impl MessageProcessor {
    /// Create a new `MessageProcessor`, retaining a handle to the outgoing
    /// `Sender` so handlers can enqueue messages to be written to stdout.
    pub(crate) fn new(args: MessageProcessorArgs) -> Self {
        Self::new_with_original_owner(args, None)
    }

    pub(crate) fn new_original_owner(
        args: MessageProcessorArgs,
        original: Arc<crate::OriginalAppServerOwnerCustody>,
    ) -> Self {
        Self::new_with_original_owner(args, Some(original))
    }

    fn new_with_original_owner(
        args: MessageProcessorArgs,
        original_owner: Option<Arc<crate::OriginalAppServerOwnerCustody>>,
    ) -> Self {
        let MessageProcessorArgs {
            outgoing,
            analytics_events_client,
            arg0_paths,
            config,
            config_manager,
            environment_manager,
            feedback,
            log_db,
            state_db,
            config_warnings,
            session_source,
            auth_manager,
            installation_id,
            code_mode_session_provider,
            rpc_transport,
            remote_control_handle,
            plugin_startup_tasks,
            turn_queue_capacity,
            hepta,
        } = args;
        let hepta = hepta.validated();
        let thread_state_manager = match &original_owner {
            Some(original) => ThreadStateManager::new_original_owner(Arc::clone(original)),
            None => ThreadStateManager::new(),
        };
        // The thread store is intentionally process-scoped. Config reloads can
        // affect per-thread behavior, but they must not move newly started,
        // resumed, or forked threads to a different persistence backend/root.
        let thread_store = codex_core::thread_store_from_config(config.as_ref(), state_db.clone());
        // Queue persistence requires SQLite, so in-memory thread stores and
        // app servers without a state database do not have a queue backend.
        let queue_store: Option<Arc<dyn QueueStore>> = match &config.experimental_thread_store {
            ThreadStoreConfig::Local => state_db.as_ref().map(|state_db| {
                let queue_store = match turn_queue_capacity {
                    Some(capacity) => {
                        LocalQueueStore::with_capacity(Arc::clone(state_db), capacity)
                    }
                    None => LocalQueueStore::new(Arc::clone(state_db)),
                };
                Arc::new(queue_store) as Arc<dyn QueueStore>
            }),
            ThreadStoreConfig::InMemory { .. } => None,
        };
        let environment_manager_for_requests = Arc::clone(&environment_manager);
        let environment_manager_for_extensions = Arc::clone(&environment_manager);
        let restriction_product = session_source.restriction_product();
        let executor_skill_provider: Arc<dyn codex_skills_extension::SkillProvider> = Arc::new(
            codex_skills_extension::ExecutorSkillProvider::new_with_restriction_product(
                Arc::clone(&environment_manager_for_extensions),
                restriction_product,
            ),
        );
        let goal_service = Arc::new(GoalService::new());
        let extension_event_sink =
            app_server_extension_event_sink(outgoing.clone(), thread_state_manager.clone());
        let mut queue_service = None;
        let thread_manager = Arc::new_cyclic(|thread_manager| {
            queue_service = queue_store.map(|queue| {
                Arc::new(QueuedItemService::new(
                    queue,
                    thread_manager.clone(),
                    Arc::clone(&extension_event_sink),
                ))
            });
            let manager = ThreadManager::new(
                config.as_ref(),
                auth_manager.clone(),
                codex_core::build_models_manager(config.as_ref(), auth_manager.clone()),
                codex_core::CodexAppsToolsCache::default(),
                session_source,
                environment_manager,
                thread_extensions(
                    guardian_agent_spawner(thread_manager.clone()),
                    ThreadExtensionDependencies {
                        event_sink: Arc::clone(&extension_event_sink),
                        auth_manager: auth_manager.clone(),
                        state_db: state_db.clone(),
                        analytics_events_client: analytics_events_client.clone(),
                        thread_manager: thread_manager.clone(),
                        goal_service: Arc::clone(&goal_service),
