    async fn handle_client_request(
        self: &Arc<Self>,
        connection_request_id: ConnectionRequestId,
        codex_request: ClientRequest,
        session: Arc<ConnectionSessionState>,
        // `Some(...)` means the caller wants initialize to immediately mark the
        // connection outbound-ready. Websocket JSON-RPC calls pass `None` so
        // lib.rs can deliver connection-scoped initialize notifications first.
        outbound_initialized: Option<&AtomicBool>,
        request_context: RequestContext,
    ) -> Result<(), JSONRPCErrorError> {
        let connection_id = connection_request_id.connection_id;
        if let ClientRequest::Initialize { request_id, params } = codex_request {
            let connection_initialized = self
                .initialize_processor
                .initialize(
                    connection_id,
                    request_id,
                    params,
                    &session,
                    outbound_initialized,
                )
                .await?;
            if connection_initialized {
                self.thread_processor
                    .connection_initialized(
                        connection_id,
                        ConnectionCapabilities {
                            request_attestation: session.request_attestation(),
                        },
                    )
                    .await;
            }
            return Ok(());
        }

        self.dispatch_initialized_client_request(
            connection_request_id,
            codex_request,
            session,
            request_context,
        )
        .await
    }

    async fn dispatch_initialized_client_request(
        self: &Arc<Self>,
        connection_request_id: ConnectionRequestId,
        codex_request: ClientRequest,
        session: Arc<ConnectionSessionState>,
        request_context: RequestContext,
    ) -> Result<(), JSONRPCErrorError> {
        if !session.initialized() {
            return Err(invalid_request("Not initialized"));
        }

        if let Some(reason) = codex_request.experimental_reason()
            && !session.experimental_api_enabled()
        {
            return Err(invalid_request(experimental_required_message(reason)));
        }
        let connection_id = connection_request_id.connection_id;
        self.initialize_processor.track_initialized_request(
            connection_id,
            connection_request_id.request_id.clone(),
            &codex_request,
        );

        let event_stream_ready = match &codex_request {
            ClientRequest::McpServerEventStreamStart { params, .. } => Some(
                session
                    .mcp_event_streams
                    .start(connection_id, params.clone(), self.mcp_processor.clone())
                    .await?,
            ),
            _ => None,
        };
        let serialization_scope = codex_request.serialization_scope();
        let error_request_id = connection_request_id.clone();
        let rpc_gate = Arc::clone(&session.rpc_gate);
        let processor = Arc::clone(self);
        let span = request_context.span();
        let request = QueuedInitializedRequest::new(
            rpc_gate,
            async move {
                let processor_for_request = Arc::clone(&processor);
                let result = processor_for_request
                    .handle_initialized_client_request(
                        connection_request_id,
                        codex_request,
                        request_context,
                        session,
                        event_stream_ready,
                    )
                    .await;
                if let Err(error) = result {
                    processor.outgoing.send_error(error_request_id, error).await;
                }
            }
            .instrument(span),
        );

        if let Some(scope) = serialization_scope {
            let (key, access) = RequestSerializationQueueKey::from_scope(connection_id, scope);
            self.request_serialization_queues
                .enqueue(key, access, request)
                .await;
        } else {
            let original_rpc = tokio::spawn(async move {
                request.run().await;
            });
            if let Some(original) =
                RequestSerializationQueues::original_owner(&self.request_serialization_queues)
            {
                crate::OriginalAppServerOwnerCustody::retain_original_task(
                    &original,
                    crate::original_owned_shutdown::OriginalAppServerTaskKind::Rpc,
                    original_rpc,
                );
            }
        }
        Ok(())
    }

    async fn handle_initialized_client_request(
        self: Arc<Self>,
        connection_request_id: ConnectionRequestId,
        codex_request: ClientRequest,
        request_context: RequestContext,
        session: Arc<ConnectionSessionState>,
        event_stream_ready: Option<McpEventStreamReady>,
    ) -> Result<(), JSONRPCErrorError> {
        let connection_id = connection_request_id.connection_id;
        let app_server_client_name = session.app_server_client_name().map(str::to_string);
        let client_version = session.client_version().map(str::to_string);
        let client_mcp_extensions = session.client_mcp_extensions();
        let request_id = ConnectionRequestId {
            connection_id,
            request_id: codex_request.id().clone(),
        };

        let response_request_id = request_id.clone();
        let outgoing = Arc::clone(&self.outgoing);
        // Most boxed request arms do not capture their context, so retain the original through
        // the final response/error send to preserve its diagnostics gauge lifetime.
        let result = Self::initialized_client_request_future(
            Arc::clone(&self),
            request_id,
            codex_request,
            request_context.clone(),
            app_server_client_name,
            client_version,
            client_mcp_extensions,
            session,
            event_stream_ready,
        )
        .await;

        match result {
            Ok(Some(response)) => {
                outgoing
                    .send_response_as(response_request_id, response)
                    .await;
            }
            Ok(None) => {}
            Err(error) => {
                outgoing.send_error(response_request_id, error).await;
            }
        }
        drop(request_context);
        Ok(())
    }

    #[inline(never)]
    #[expect(
        clippy::too_many_arguments,
        reason = "request dispatch keeps connection, client and stream context explicit"
    )]
    fn initialized_client_request_future(
        processor: Arc<Self>,
        request_id: ConnectionRequestId,
        codex_request: ClientRequest,
        request_context: RequestContext,
        app_server_client_name: Option<String>,
        client_version: Option<String>,
        client_mcp_extensions: ClientMcpExtensions,
        session: Arc<ConnectionSessionState>,
        event_stream_ready: Option<McpEventStreamReady>,
    ) -> InitializedClientRequestFuture {
        let connection_id = request_id.connection_id;
        boxed_request_match!(codex_request, {
            ClientRequest::Initialize { .. } => {
                reject_initialized_dispatch_of_initialize()
            },
            ClientRequest::ServerDiagnostics { .. } => Ok(Some(read_server_diagnostics().into())),
            ClientRequest::ConfigRead { params, .. } => processor
                .config_processor
                .read(params)
                .await
                .map(|response| Some(response.into())),
            ClientRequest::WindowsSandboxReadiness { .. } => processor
                .windows_sandbox_processor
                .windows_sandbox_readiness()
                .await
                .map(|response| Some(response.into())),
            ClientRequest::ExternalAgentConfigDetect { params, .. } => processor
                .external_agent_config_processor
                .detect(params)
                .await
                .map(|response| Some(response.into())),
            ClientRequest::ExternalAgentConfigImport { params, .. } => processor
                .external_agent_config_processor
                .import(request_id.clone(), params)
                .await
                .map(|()| None),
            ClientRequest::ExternalAgentConfigImportHistoryRecord { params, .. } => processor
                .external_agent_config_processor
                .record_import_history(params)
                .await
                .map(|response| Some(response.into())),
            ClientRequest::ExternalAgentConfigImportHistoriesRead { .. } => processor
                .external_agent_config_processor
                .read_import_histories()
                .await
                .map(|response| Some(response.into())),
            ClientRequest::ConfigValueWrite { params, .. } => {
                processor.config_processor.value_write(params).await.map(Some)
            },
            ClientRequest::ConfigBatchWrite { params, .. } => {
                processor.config_processor.batch_write(params).await.map(Some)
